"""Builds reports/BACKTEST3Y_REGIME.md and figures/bl_bt3_regime.png from outputs/bt3_results/regime_*.csv (plan reports/BACKTEST3Y_REGIME_PLAN.md)."""
import sys, os, json, warnings; sys.path.insert(0, '.'); warnings.filterwarnings('ignore')
import numpy as np, pandas as pd, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
OUT = os.path.join(os.path.dirname(os.path.abspath('.')), 'outputs'); RES = f'{OUT}/bt3_results'; RP = os.path.join(os.path.dirname(OUT), 'reports'); FIG = os.path.join(RP, 'figures')
def _md(self, index=True, **kw):
    d = self.reset_index() if index else self
    h = '| ' + ' | '.join(str(c) for c in d.columns) + ' |\n|' + '---|' * len(d.columns) + '\n'
    f = lambda v: ('' if pd.isna(v) else (f'{v:g}' if isinstance(v, (float, np.floating)) else str(v)))
    return h + '\n'.join('| ' + ' | '.join(f(v) for v in r) + ' |' for r in d.itertuples(index=False))
pd.DataFrame.to_markdown = _md
W = pd.read_csv(f'{RES}/regime_weeks.csv', parse_dates=['date']); C = pd.read_csv(f'{RES}/regime_cycles.csv'); ST = pd.read_csv(f'{RES}/regime_stationarity.csv'); FM = pd.read_csv(f'{RES}/regime_families.csv'); CE = pd.read_csv(f'{RES}/regime_cells.csv'); J = json.load(open(f'{RES}/regime_summary.json'))
k = lambda x: f'{x / 1e3:,.0f}k'; pc = lambda x, d=0: f'{100 * x:.{d}f}%'; st = ST.set_index('series')
# ---- gap deep dive
q = W.open_gap.quantile([1 / 3, 2 / 3]).values; order = ['low', 'mid', 'high']
G_mod = W.groupby('open_gap_t')[['net', 'gross', 'd1only', 'd0adds', 'altA_net']].mean().reindex(order).round(0).reset_index().rename(columns={'open_gap_t': 'gap tercile', 'net': 'net', 'd1only': 'D-1 book alone (net)', 'd0adds': 'D0 module adds (net)', 'altA_net': 'net, A/V1 band'})
G_split = W.pivot_table(index='split', columns='open_gap_t', values='net', aggfunc='mean').reindex(columns=order).round(0); G_split['weeks (low/mid/high)'] = [' / '.join(str(int(((W.split == s) & (W.open_gap_t == t)).sum())) for t in order) for s in G_split.index]; G_split = G_split.reset_index()
C['gap_t'] = pd.cut(C.open_gap, [-1, q[0], q[1], 99], labels=order); G_idx = C.pivot_table(index='und', columns='gap_t', values='net_k', aggfunc='mean').round(0).reset_index(); G_stop = C.assign(stop=C.stop_j.notna()).groupby('gap_t').stop.mean().reindex(order)
F = W[W.month == 2].copy(); F['year'] = F.date.dt.year; FEB = F.groupby('year').net.agg(weeks='size', mean_net='mean').round(0).reset_index()
sd = W.net.std(); n_need = (2.8 * sd / 150000) ** 2
# ---- figure
fig, ax = plt.subplots(2, 2, figsize=(15, 9))
ax[0, 0].plot(W.date, W.roll26 / 1e3, color='k'); ax[0, 0].fill_between(W.date, W.roll26_lo / 1e3, W.roll26_hi / 1e3, color='k', alpha=.15); ax[0, 0].axhline(W.net.mean() / 1e3, color='#c05621', ls='--', label=f'overall mean ({W.net.mean() / 1e3:.0f}k)'); ax[0, 0].axhline(0, color='k', lw=.6); ax[0, 0].set_title(f'Rolling 26-week mean net per cycle (₹ thousand); variability vs shuffled weeks p = {st.loc["net", "roll26_sd_p"]:.2f}'); ax[0, 0].legend(fontsize=8); ax[0, 0].tick_params(axis='x', rotation=30)
m = CE[CE.family == 'month of year'].copy(); m['mn'] = m.cell.astype(int); m = m.sort_values('mn'); ax[0, 1].bar(m.mn, m.mean_net / 1e3, color=['#2b6cb0' if v < 0.10 else '#999999' for v in m.q_bh]); ax[0, 1].errorbar(m.mn, m.mean_net / 1e3, yerr=[(m.mean_net - m.lo) / 1e3, (m.hi - m.mean_net) / 1e3], fmt='none', color='k', capsize=2); ax[0, 1].axhline(0, color='k', lw=.6)
ax[0, 1].set_xticks(range(1, 13)); ax[0, 1].set_xticklabels(list('JFMAMJJASOND')); ax[0, 1].set_title(f'Month of year, mean net (₹ thousand), 95% CI\nblue = cell q < 0.10; family permutation p = {FM[FM.family == "month of year"].family_p.iloc[0]:.2f}', fontsize=10)
x = np.arange(3); w = .27
for i, (sp, col) in enumerate((('IS', '#555555'), ('OOS', '#2b6cb0'), ('LIVE_FITTED', '#c05621'))): v = G_split[G_split.split == sp][order].values[0] / 1e3; ax[1, 0].bar(x + (i - 1) * w, v, w, color=col, label=sp)
ax[1, 0].set_xticks(x); ax[1, 0].set_xticklabels([f'low gap\n(< {q[0]:.2f}%)', f'mid gap\n({q[0]:.2f}–{q[1]:.2f}%)', f'high gap\n(> {q[1]:.2f}%)']); ax[1, 0].axhline(0, color='k', lw=.6); ax[1, 0].set_ylabel('mean net per cycle (₹ thousand)'); ax[1, 0].set_title('The opening-gap effect by split (weekly means)'); ax[1, 0].legend(fontsize=8)
yy = FM.copy(); yy['sig'] = yy.p_holm; yy = yy.sort_values('family_p'); ax[1, 1].barh(yy.family, -np.log10(yy.family_p.clip(lower=1 / 5000)), color=['#2b6cb0' if s else '#999999' for s in yy.supported]); ax[1, 1].axvline(-np.log10(0.05), color='k', ls=':'); ax[1, 1].set_xlabel('−log10 permutation p of the family (dotted = 0.05, before Holm)'); ax[1, 1].set_title('Which families beat shuffled labels?'); ax[1, 1].invert_yaxis(); ax[1, 1].tick_params(axis='y', labelsize=7)
plt.tight_layout(); plt.savefig(os.path.join(FIG, 'bl_bt3_regime.png'), dpi=120); plt.close()
# ---- report
L = []; w_ = L.append
w_('# Is the edge seasonal, or does it only work in some periods?\n')
w_('*Plan `BACKTEST3Y_REGIME_PLAN.md`, written before the tests. **Exploratory**: every cycle (IS, OOS, rule-fitted live window) is used and no untouched data remain. Unit = ISO week at a constant lot size. Scripts `bl_bt3_regime.py`, `make_regime_report.py`; figure `figures/bl_bt3_regime.png`.*\n')
w_('## 0. Answer\n')
w_(f'**No evidence that the edge is seasonal or confined to a period. The one thing that does separate good weeks from bad weeks is the size of the overnight/opening gap, and that finding is fragile.**\n')
w_('| question | answer | evidence |\n|---|---|---|')
w_(f'| Does it work only in some stretch of time? | **No evidence of that.** {pc(J["share_weeks_positive"])} of weeks are positive; the rolling 26-week mean moves no more than shuffled weeks do (p = {st.loc["net","roll26_sd_p"]:.2f}); no change point (p = {st.loc["net","changepoint_p"]:.2f}); weeks are uncorrelated (lag-1 autocorrelation {st.loc["net","acf1"]:.2f}, band ±{st.loc["net","acf_band"]:.2f}). **The latest 26 weeks are the weakest stretch of the series (₹{k(W.roll26.iloc[-1])} per cycle, interval {k(W.roll26_lo.iloc[-1])} to {k(W.roll26_hi.iloc[-1])}), still inside the noise band;** if it is decay it would take more weeks to show. First half ₹{k(st.loc["net","first_half_mean"])}, second half ₹{k(st.loc["net","second_half_mean"])} per cycle: difference {k(st.loc["net","diff"])} (CI {k(st.loc["net","diff_lo"])} to {k(st.loc["net","diff_hi"])}), not significant. | Observed |')
w_(f'| Is there a seasonal (calendar) pattern? | **Not supported.** Month of year p = {FM[FM.family=="month of year"].family_p.iloc[0]:.2f}, quarter {FM[FM.family=="quarter"].family_p.iloc[0]:.2f}, week of month {FM[FM.family=="week of month (D0)"].family_p.iloc[0]:.2f}, year {FM[FM.family=="calendar year"].family_p.iloc[0]:.2f}, half-year {FM[FM.family=="half-year"].family_p.iloc[0]:.2f}, monthly-expiry week {FM[FM.family=="monthly-expiry week"].family_p.iloc[0]:.2f} (family tests, before Holm). | Observed |')
w_(f'| But February looks great. | February: ₹{k(CE[(CE.family=="month of year")&(CE.cell=="2")].mean_net.iloc[0])} per cycle-week, {pc(CE[(CE.family=="month of year")&(CE.cell=="2")].win_weeks.iloc[0])} winning weeks, cell q = {CE[(CE.family=="month of year")&(CE.cell=="2")].q_bh.iloc[0]:.3f}. **But one of 12 months will look like that by chance**: the family test across the 12 months does not beat shuffled labels. All three Februaries are positive (₹{k(FEB.mean_net.iloc[0])}, ₹{k(FEB.mean_net.iloc[1])}, ₹{k(FEB.mean_net.iloc[2])}); three observations are a hypothesis (the Union Budget is in that month), not a season. | Observed; hypothesis only |')
gg = FM[FM.family.str.startswith('opening gap')].iloc[0]
w_(f'| What does separate good weeks from bad? | **The opening gap on D0** (D0 open vs D-1 close): family p = {gg.family_p:.3f}, Holm {gg.p_holm:.3f}, the only supported family of 14. Net per cycle ₹{k(G_mod.net.iloc[0])} (gap < {q[0]:.2f}% of spot), ₹{k(G_mod.net.iloc[1])} ({q[0]:.2f}–{q[1]:.2f}%), **₹{k(G_mod.net.iloc[2])} (> {q[1]:.2f}%)**. Cycle stops rise from {pc(G_stop.iloc[0])} to {pc(G_stop.iloc[1])} to {pc(G_stop.iloc[2])}. | Observed |')
w_(f'| Is the gap effect robust? | **Only partly.** It is monotone in-sample and in the rule-fitted window, but **not out of sample** (low / mid / high ₹{k(G_split[G_split.split=="OOS"].low.iloc[0])} / ₹{k(G_split[G_split.split=="OOS"].mid.iloc[0])} / ₹{k(G_split[G_split.split=="OOS"].high.iloc[0])}); it is strong in SENSEX and weak in NIFTY; and the loss sits in the **carried D-1 book** (₹{k(G_mod["D-1 book alone (net)"].iloc[2])} per week in high-gap weeks against ₹{k(G_mod["D-1 book alone (net)"].iloc[0])} in low-gap weeks), while the D0 module still adds ₹{k(G_mod["D0 module adds (net)"].iloc[2])}. It is the overnight risk of the carry, not a calendar effect, and the gap is not known when the D-1 book is built. | Observed |')
w_(f'| Is the P&L explained by the usual short-premium story? | **No.** The weekly net is unrelated to the realised ÷ implied ratio (Spearman {J["mechanism_spearman_ratio_net"]:.2f}, p = {J["mechanism_p"]:.2f}), to the realised move ({J["spearman_realised_net"]:.2f}) and to the implied move ({J["spearman_implied_net"]:.2f}). A hedged, stop-managed book of ≈ 1,300 orders per cycle does not behave like a plain short straddle. | Observed |\n')
w_(f'**Power.** The weekly net has mean ₹{k(W.net.mean())}, standard deviation ₹{k(sd)}, standard error ₹{k(sd/np.sqrt(len(W)))} on {len(W)} weeks. To detect a calendar effect of ₹150k per cycle in a single month at 80% power you need about {n_need:.0f} weeks of that month, i.e. ≈ {n_need/4.3:.0f} years. **This sample cannot find a seasonal effect of this size even if one exists.**\n')
w_('## 1. Stationarity (weekly net, constant lot size)\n'); w_(ST[['series', 'weeks', 'mean', 'roll26_sd', 'roll26_sd_p', 'changepoint_t', 'changepoint_week', 'changepoint_p', 'first_half_mean', 'second_half_mean', 'diff', 'diff_lo', 'diff_hi', 'acf1', 'acf2', 'acf3', 'acf4']].round(3).to_markdown(index=False) + '\n')
w_('*Series: net = B/V2 point line; gross = before slippage and costs; altA_net = timetable A/V1 band; d1only = the D-1 book managed alone; d0adds = what the D0 module adds. `roll26_sd_p` = chance that shuffled weeks vary as much as the real rolling means (small = regimes). `changepoint_p` = chance that shuffled weeks contain a split at least as pronounced.*\n')
w_('## 2. Families (permutation test of the labels, Holm over the 14 families)\n'); w_(FM[['family', 'groups', 'family_p', 'p_holm', 'best_cell_q', 'sign_ok', 'supported']].round(4).to_markdown(index=False) + '\n')
w_(f'*Supported = family permutation p < 0.05 after Holm AND a cell with FDR q < 0.10 AND the same sign in the A/V1 band and in the gross series. `best_cell_q` is the smallest Benjamini–Hochberg q among the family\'s cells ({J["cells"]} cells in total).*\n')
w_('## 3. Cells\n'); w_(CE[['family', 'cell', 'weeks', 'mean_net', 'lo', 'hi', 'p_cell', 'q_bh', 'mean_gross', 'mean_altA_net', 'win_weeks']].round(3).to_markdown(index=False) + '\n')
w_('## 4. The opening-gap effect in detail\n'); w_(f'Tercile edges of the weekly mean opening gap: {q[0]:.3f}% and {q[1]:.3f}% of spot.\n'); w_('**By module (mean per week, ₹)**\n'); w_(G_mod.to_markdown(index=False) + '\n'); w_('**By split (net, ₹)**\n'); w_(G_split.to_markdown(index=False) + '\n'); w_('**By index (cycle level, net at constant lot size, ₹)**\n'); w_(G_idx.to_markdown(index=False) + '\n')
w_('## 5. How to find out for real (what would confirm any of this)\n')
w_('* **Write the rule down now, test it on cycles that do not exist yet.** For the gap: the candidate is "the D-1 carry loses when the next opening gap is large", which is a risk to size the overnight protection against, not a filter (the gap is unknown when D-1 trades). For February: "February weeks outperform", to be checked on February 2027 (4–5 weeks).')
w_('* **A forward test needs about as many cycles as the effect is small.** At the sd above, a month-specific effect needs ≈ 4 years; a gap effect (₹130k vs −₹28k, a far larger difference) is testable in 1–2 years of paper trading.')
w_('* **Collect what the sample lacks:** earlier years (the validated dataset starts in November 2023), ideally through 2020–2022 with the same one-minute option data, which would add independent repeats of every month and a different volatility regime.')
w_('* **If a rule is added, it is a new strategy** and goes through the pre-registered in-sample / out-of-sample procedure again; the cycles used here are no longer untouched.\n')
w_('## 6. Adversarial read\n')
w_(f'* **Multiple looks.** 14 families, {J["cells"]} cells, and the OOS cycles were already seen. The correction (Holm over families, FDR over cells) controls false positives within this list, not the earlier looks; one supported family of 14 at Holm 0.028 is a hypothesis.')
w_('* **The weekly unit throws away information** but removes the dependence between NIFTY and SENSEX cycles of the same week; cycle-level families (index, weekday) use within-week permutations.')
w_('* **The timetable before June 2026 is assumed** (B/V2). A period effect in 2023–2025 could come from that assumption; the A/V1 band shows the same stationarity result (`altA_net` row).')
w_('* **Lot size.** Everything is restated at the 2026 lot sizes; costs are the earlier model\'s and partly fixed in rupees (brokerage), so older years with smaller lots carry relatively more cost.')
w_('* **Absence of evidence is not evidence of absence** (see Power).\n')
open(f'{RP}/BACKTEST3Y_REGIME.md', 'w').write('\n'.join(L)); print('written', len('\n'.join(L)))
